// Virtual-dtor leaf patterns (SQZ.EXE):
//  - the scalar-deleting-destructor `??_G` (see .cpp): auto-generated by a trivial `virtual ~T() {}`.
//  - the complete-object-destructor `~T` (just `mov [ecx],<vtable>; ret`): hand-written below.
#pragma once
#include "compat41.h"

struct VirtualDtorObj {
    virtual ~VirtualDtorObj() {}
};

struct FlatDtor {
    void **vtbl;       // 0x00
    void Dtor();       // mov [ecx],<vtable>; ret (7 bytes)
};
